<script setup>
import PageHeading from '../components/ui/PageHeading.vue'
import {ref,reactive,onMounted} from 'vue'
import {RouterLink} from 'vue-router'
import {useAuthStore} from '../stores/auth.js'
const auth=useAuthStore(),form=reactive({retentionDays:90,staleSeconds:120,note:''}),busy=ref(false),error=ref(''),result=ref(null),feedback=ref('')
async function act(fn){busy.value=true;error.value='';feedback.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(()=>act(async()=>{const p=await auth.request('/api/manage/location-policy',undefined,'GET');form.retentionDays=p.retentionDays;form.staleSeconds=p.staleSeconds}))
async function save(){await act(async()=>{await auth.request('/api/manage/location-policy',{...form},'PATCH');result.value=null;feedback.value='Location policy saved. No records have been deleted.'})}
async function retention(dryRun){if(!dryRun&&!window.confirm('Permanently purge up to 1,000 expired location observations and their derived movement events? Audit, workers, telemetry and incidents are retained.'))return;await act(async()=>{result.value=await auth.request('/api/manage/location-retention',{dryRun,note:form.note,...(!dryRun?{confirmation:'PURGE_EXPIRED_LOCATIONS'}:{})})})}
</script>
<template><main class="connectivity-page"><nav><RouterLink to="/tracking">← Tracking</RouterLink></nav><PageHeading title="Location privacy & retention" eyebrow="DACOS / OPERATIONS"/><p>Admin-only controls. Retention defaults to 90 days and location freshness to 120 seconds. Configure these for the approved site policy. Saving policy does not delete records.</p><p v-if="error" role="alert">{{error}}</p><p v-if="feedback" role="status">{{feedback}}</p><section><form @submit.prevent="save"><label>Retain visible history (days)<input v-model.number="form.retentionDays" type="number" min="1" max="3650" required></label><label>Location becomes stale after (seconds)<input v-model.number="form.staleSeconds" type="number" min="10" max="86400" required></label><label>Reason / review note<input v-model="form.note" minlength="3" maxlength="1000" required></label><button :disabled="busy">Save policy</button></form></section><section><h2>Expired location cleanup</h2><p>History queries respect the saved retention window. Cleanup is manual, audited and limited to 1,000 observations per action. It also removes derived events attached to those observations. No background purge runs.</p><button :disabled="busy||form.note.trim().length<3" @click="retention(true)">Preview expired observations</button><div v-if="result" role="status"><p>Cutoff {{result.cutoff}} · Expired {{result.expired}} · Deleted {{result.deleted}} · {{result.dryRun?'Preview only':'Purge completed'}}</p><button v-if="result.expired&&result.dryRun" :disabled="busy" @click="retention(false)">Confirm purge of expired locations</button></div></section></main></template>
